SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name": "Digital Gross Revenue", "domainName": "Game Commerce", "itemKind": "METRIC", "description": "Gross value of all digital store sales, before platform commission. Grain: one row per purchase in DIGITAL_PRODUCT_TRANSACTIONS. Include every row: do NOT filter TITLE_ID IS NOT NULL; about 1 in 10 rows has no TITLE_ID but still belongs to a game through DIGITAL_PRODUCT_ID -> DIGITAL_PRODUCTS.TITLE_ID. Region: join PLAYER_ID to CUSTOMER_ACCOUNTS (SIE Region Code). Additive across games, products, customers and time. Includes physical editions sold as BASE_GAME_PHYSICAL (see Revenue Type Code).", "synonyms": ["Digital Revenue", "Digital Sales"], "formula": "SUM(GROSS_REVENUE) FROM ONTOLOGY_DEMO.GAME_SALES.DIGITAL_PRODUCT_TRANSACTIONS"}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name": "Net Publisher Revenue", "domainName": "Game Commerce", "itemKind": "METRIC", "description": "Net digital revenue the Publisher keeps after the store commission. Grain: one row per digital purchase. The column is named NET_DEVELOPER_REVENUE but it is the PUBLISHER share, not the Developer''s (developers are studios owned by the publisher and get no separate share). Do not report gross for this question. Same row rules as Digital Gross Revenue (keep rows with NULL TITLE_ID). Additive.", "synonyms": ["Publisher Share", "Net Revenue After Commission"], "formula": "SUM(NET_DEVELOPER_REVENUE) FROM ONTOLOGY_DEMO.GAME_SALES.DIGITAL_PRODUCT_TRANSACTIONS"}');
