SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name": "Battle Pass Sales Revenue", "domainName": "Game Commerce", "itemKind": "METRIC", "description": "Gross revenue from battle passes actually SOLD: digital purchases whose product''s Revenue Type Code is BATTLE_PASS. Not the same as games tagged with a battle_pass business model in MONETIZATION_TYPES, which is a tag with no money attached. Grain: one row per digital purchase. Additive.", "synonyms": ["Battle Pass Revenue"], "formula": "SUM(t.GROSS_REVENUE) FROM DIGITAL_PRODUCT_TRANSACTIONS t JOIN DIGITAL_PRODUCTS p USING (DIGITAL_PRODUCT_ID) JOIN REVENUE_TYPES r ON r.CATEGORY_ID = p.CATEGORY_ID WHERE r.MONETIZATION_TYPE = ''BATTLE_PASS''"}');
