SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name": "Game Identity Match Rule", "domainName": "Game Catalog", "itemKind": "TERM", "description": "Policy for resolving a Sales title to a catalog Game, in order: (1) strong: TITLES.CATALOG_GAME_ID; (2) medium: TITLE_CODE_XREF.CATALOG_GAME_ID for the title; (3) weak: same name ignoring case and accents AND same release year, exactly: COLLATE(TITLES.TITLE_NAME, ''en-ci-ai'') = COLLATE(GAMES.GAME_NAME, ''en-ci-ai'') AND LEFT(TITLES.RELEASE_DATE, 4) = TO_CHAR(YEAR(GAMES.RELEASE_DATE)) (TITLES.RELEASE_DATE is text YYYYMMDD and may be the JP date). LOWER() or TRIM() alone do NOT remove accents, so a plain LOWER(name) comparison misses titles spelled without accents in Sales. Apply all three routes; skipping (2) and (3) leaves titles unmatched and undercounts revenue.", "synonyms": ["Title to Game Match"]}');
