SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name": "SIE Region Code", "domainName": "Game Commerce", "itemKind": "TERM", "description": "CUSTOMER_ACCOUNTS.REGION: SIEA = North America, SIEE = Europe, SIEJ = Japan, SIEAP = Asia-Pacific, SIELA = Latin America.", "synonyms": ["Customer Region"]}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name": "Sales Region Code", "domainName": "Game Commerce", "itemKind": "TERM", "description": "HARDWARE_SALES_TRANSACTIONS.REGION: NA = North America, EU = Europe, JP = Japan, ASIA = Asia-Pacific, LATAM = Latin America.", "synonyms": ["Hardware Region"]}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name": "Account Status", "domainName": "Game Commerce", "itemKind": "TERM", "description": "CUSTOMER_ACCOUNTS.STATUS: A = active, S = suspended, C = closed. Active customers = ''A'' only."}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name": "Listing Status", "domainName": "Game Commerce", "itemKind": "TERM", "description": "DIGITAL_PRODUCTS.STATUS: LIVE, DELISTED (store availability of a product)."}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name": "Exclusivity Flag", "domainName": "Game Commerce", "itemKind": "TERM", "description": "Sales GAME_PLATFORMS.IS_EXCLUSIVE is text ''Y''/''N'' (Catalog uses BOOLEAN). Currently exclusive = PERMANENT, or TIMED with EXCLUSIVE_END >= today."}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name": "POV Code", "domainName": "Genre Taxonomy", "itemKind": "TERM", "description": "GAMES.POV: 1P = first person, 3P = third person.", "synonyms": ["Point of View", "Perspective"]}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name": "Genre Roll-up Rule", "domainName": "Genre Taxonomy", "itemKind": "TERM", "description": "How to count or sum a genre including its subgenres. GAME_CATALOG.VW_GAME_GENRE_ROLLUP (logical table GENRE_ROLLUP) has one row per game per genre it belongs to: each FULL-matched genre plus all its ancestors in the PARENT_GENRE tree; ROLLUP_DEPTH 1 = top-level genre. (1) For a parent or top-level genre use GENRE_ROLLUP.ROLLUP_GENRE, never GENRE_CLASSIFICATION.GENRE (parents have no FULL rows of their own). (2) The tree is single-parent, so RPG members must be added by hand: RPG = games with ROLLUP_GENRE IN (''RPG'', ''ActionRPG'', ''Soulslike'', ''Roguelike''), counted with COUNT(DISTINCT GAME_ID). (3) A game counts once per genre and belongs to several genres, so per-genre counts and revenue overlap and are not additive. (4) ''Which genre'' ranks top-level genres (ROLLUP_DEPTH = 1, plus RPG per rule 2) unless subgenres are asked for.", "synonyms": ["Genre Hierarchy Rule", "Parent Genre Rule"]}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name": "Genre Match Status", "domainName": "Genre Taxonomy", "itemKind": "TERM", "description": "GAME_GENRE_CLASSIFICATION.MATCH_STATUS: FULL = member; PARTIAL, NONE, UNEVALUABLE = not a member."}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name": "Genre Rule", "domainName": "Genre Taxonomy", "itemKind": "TERM", "description": "GENRE_RULES is the executable source (used by SP_CLASSIFY_GAMES). RULE_DEFINITION syntax: hasX VALUE v (exact value), hasX SOME Category (any value in a GENRE_CATEGORY_MAP category), MIN/MAX (player count), NOT(...), INTERSECTION(...) = AND. PARENT_GENRE is single-parent BY DESIGN: ActionRPG and Soulslike sit under Action, so the strict tree alone finds no RPG members; the ontology links them to RPG. Disjoint pairs: FPS-TPS, MMO-LocalMultiplayer, Cozy-Horror, Artistic-Realistic, MMO-SinglePlayer. Genres held as values only (no node): DynamicAdventure, Survival, Explorative, FamiliarExploration, FantasyExploration, InteractiveMovie, Metroidvania, VisualNovel, Gore, Psychological, SurvivalHorror, Roguelike, Tactic, BattleRoyale, Match, Scrolling, DatingSim, DrivingSim, JobSim, Management, SandBox, Sport, Artistic, Educational, PuzzleGame, Cozy, Other, LiveService, MultiplayerAvailable, MMO, LocalMultiplayer, Genre (root).", "synonyms": ["Genre Definition"]}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name": "Action", "domainName": "Genre Taxonomy", "itemKind": "TERM", "description": "Genre. Top-level. Members = union of Shooter, Fighting, Platformer, Stealth, Survival, ActionRPG, DynamicAdventure and their subgenres. Membership: FULL match in GAME_GENRE_CLASSIFICATION; a parent''s members are the union of its descendants, queryable as GENRE_ROLLUP.ROLLUP_GENRE = ''Action'' (VW_GAME_GENRE_ROLLUP; see Genre Roll-up Rule). Source value GENRE_RULES.GENRE = ''Action''.", "synonyms": ["action games"]}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name": "Adventure", "domainName": "Genre Taxonomy", "itemKind": "TERM", "description": "Genre. Top-level. Includes Explorative, InteractiveMovie, Metroidvania, VisualNovel. Membership: FULL match in GAME_GENRE_CLASSIFICATION; a parent''s members are the union of its descendants, queryable as GENRE_ROLLUP.ROLLUP_GENRE = ''Adventure'' (VW_GAME_GENRE_ROLLUP; see Genre Roll-up Rule). Source value GENRE_RULES.GENRE = ''Adventure''.", "synonyms": ["adventure games"]}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name": "RPG", "domainName": "Genre Taxonomy", "itemKind": "TERM", "description": "Genre. Top-level. Members = RPG + Roguelike + ActionRPG + Soulslike. ActionRPG and Soulslike sit under Action in GENRE_RULES, so ROLLUP_GENRE = ''RPG'' alone misses them; always use ROLLUP_GENRE IN (''RPG'', ''Roguelike'', ''ActionRPG'', ''Soulslike''). Count distinct games. Membership: FULL match in GAME_GENRE_CLASSIFICATION; a parent''s members are the union of its descendants, queryable as GENRE_ROLLUP.ROLLUP_GENRE = ''RPG'' (VW_GAME_GENRE_ROLLUP; see Genre Roll-up Rule). Source value GENRE_RULES.GENRE = ''RPG''.", "synonyms": ["role-playing game", "roleplaying game"]}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name": "Horror", "domainName": "Genre Taxonomy", "itemKind": "TERM", "description": "Genre. Top-level. Includes Gore, Psychological, SurvivalHorror. Disjoint with Cozy. Membership: FULL match in GAME_GENRE_CLASSIFICATION; a parent''s members are the union of its descendants, queryable as GENRE_ROLLUP.ROLLUP_GENRE = ''Horror'' (VW_GAME_GENRE_ROLLUP; see Genre Roll-up Rule). Source value GENRE_RULES.GENRE = ''Horror''.", "synonyms": ["horror games"]}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name": "Simulator", "domainName": "Genre Taxonomy", "itemKind": "TERM", "description": "Genre. Top-level. Includes DatingSim, DrivingSim, JobSim, Management, SandBox, Sport. Most sim rules are unmet by the data. Membership: FULL match in GAME_GENRE_CLASSIFICATION; a parent''s members are the union of its descendants, queryable as GENRE_ROLLUP.ROLLUP_GENRE = ''Simulator'' (VW_GAME_GENRE_ROLLUP; see Genre Roll-up Rule). Source value GENRE_RULES.GENRE = ''Simulator''.", "synonyms": ["sim", "simulation game"]}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name": "Strategic", "domainName": "Genre Taxonomy", "itemKind": "TERM", "description": "Genre. Top-level leaf. Membership: FULL match in GAME_GENRE_CLASSIFICATION; a parent''s members are the union of its descendants, queryable as GENRE_ROLLUP.ROLLUP_GENRE = ''Strategic'' (VW_GAME_GENRE_ROLLUP; see Genre Roll-up Rule). Source value GENRE_RULES.GENRE = ''Strategic''.", "synonyms": ["strategy", "strategy game"]}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name": "Shooter", "domainName": "Genre Taxonomy", "itemKind": "TERM", "description": "Genre. Parent Action. Rule hasGameplay VALUE free_shooting. Variants FPS and TPS (axis: point of view). Membership: FULL match in GAME_GENRE_CLASSIFICATION; a parent''s members are the union of its descendants, queryable as GENRE_ROLLUP.ROLLUP_GENRE = ''Shooter'' (VW_GAME_GENRE_ROLLUP; see Genre Roll-up Rule). Source value GENRE_RULES.GENRE = ''Shooter''.", "synonyms": ["shooter games", "gunplay"]}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name": "FPS", "domainName": "Genre Taxonomy", "itemKind": "TERM", "description": "Genre. Variant of Shooter with POV 1P. Disjoint with TPS. Use GENRE = ''FPS''; ''first-person shooter'' is not a stored value. Membership: FULL match in GAME_GENRE_CLASSIFICATION; a parent''s members are the union of its descendants, queryable as GENRE_ROLLUP.ROLLUP_GENRE = ''FPS'' (VW_GAME_GENRE_ROLLUP; see Genre Roll-up Rule). Source value GENRE_RULES.GENRE = ''FPS''.", "synonyms": ["first-person shooter", "first person shooter"]}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name": "TPS", "domainName": "Genre Taxonomy", "itemKind": "TERM", "description": "Genre. Variant of Shooter with POV 3P. Membership: FULL match in GAME_GENRE_CLASSIFICATION; a parent''s members are the union of its descendants, queryable as GENRE_ROLLUP.ROLLUP_GENRE = ''TPS'' (VW_GAME_GENRE_ROLLUP; see Genre Roll-up Rule). Source value GENRE_RULES.GENRE = ''TPS''.", "synonyms": ["third-person shooter", "third person shooter"]}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name": "ActionRPG", "domainName": "Genre Taxonomy", "itemKind": "TERM", "description": "Genre. Parent Action; also an RPG. Membership: FULL match in GAME_GENRE_CLASSIFICATION; a parent''s members are the union of its descendants, queryable as GENRE_ROLLUP.ROLLUP_GENRE = ''ActionRPG'' (VW_GAME_GENRE_ROLLUP; see Genre Roll-up Rule). Source value GENRE_RULES.GENRE = ''ActionRPG''.", "synonyms": ["action RPG", "ARPG"]}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name": "Soulslike", "domainName": "Genre Taxonomy", "itemKind": "TERM", "description": "Genre. Parent ActionRPG; also an RPG. Its rule needs melee_combat and a difficulty attribute that do not exist in the data, so it has no FULL matches. Membership: FULL match in GAME_GENRE_CLASSIFICATION; a parent''s members are the union of its descendants, queryable as GENRE_ROLLUP.ROLLUP_GENRE = ''Soulslike'' (VW_GAME_GENRE_ROLLUP; see Genre Roll-up Rule). Source value GENRE_RULES.GENRE = ''Soulslike''.", "synonyms": ["Soulsborne", "souls-like"]}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name": "Fighting", "domainName": "Genre Taxonomy", "itemKind": "TERM", "description": "Genre. Parent Action. Includes Match, Scrolling. Membership: FULL match in GAME_GENRE_CLASSIFICATION; a parent''s members are the union of its descendants, queryable as GENRE_ROLLUP.ROLLUP_GENRE = ''Fighting'' (VW_GAME_GENRE_ROLLUP; see Genre Roll-up Rule). Source value GENRE_RULES.GENRE = ''Fighting''.", "synonyms": ["fighter", "versus fighting"]}');
SELECT SYSTEM$DRAFT_GLOSSARY_TERM('{"name": "Platformer", "domainName": "Genre Taxonomy", "itemKind": "TERM", "description": "Genre. Parent Action. Not the Platform entity. Membership: FULL match in GAME_GENRE_CLASSIFICATION; a parent''s members are the union of its descendants, queryable as GENRE_ROLLUP.ROLLUP_GENRE = ''Platformer'' (VW_GAME_GENRE_ROLLUP; see Genre Roll-up Rule). Source value GENRE_RULES.GENRE = ''Platformer''.", "synonyms": ["platform game", "platforming"]}');
